void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
struct Surface {
 MainWindow window;WorksheetView* view;WorksheetModel* model;QLineEdit* bar;
 Surface(){window.resize(1400,850);window.show();view=dynamic_cast<WorksheetView*>(window.findChild<QTableView*>("worksheet.grid"));model=dynamic_cast<WorksheetModel*>(view->model());bar=window.findChild<QLineEdit*>("formula.input");require(view&&model&&bar,"native workbook exposes its grid and formula editor");installExternalReferenceEntry(window,*view,*bar);}
 void activate(){window.activateWindow();view->setFocus();QApplication::processEvents();}
};
void externalPointAfterWindowActivation(){
 for(bool inCell:{false,true}){
  QTemporaryDir files;Surface origin,source;
  require(origin.model->setData(origin.model->index(0,0),"17")&&source.model->setData(source.model->index(1,1),"42")&&source.window.saveWorkbook(files.filePath("Activated Source.xlsx")),"prepare independent named source and original value");
  const auto before=origin.window.currentSession().snapshot(),sourceBefore=source.window.currentSession().snapshot();origin.activate();QLineEdit* editor=origin.bar;
  if(inCell){QTest::keyClick(origin.view,Qt::Key_F2);editor=origin.view->activeCellEditor();require(editor,"window activation fixture opens the actual inline editor");}
  editor->setFocus();editor->selectAll();QTest::keyClicks(editor,"=");
  source.activate();
  require(QApplication::activeWindow()==&source.window&&origin.window.currentSession().snapshot()==before&&source.window.currentSession().snapshot()==sourceBefore,"activating another workbook preserves the uncommitted formula and both histories without CtrlTab");
  QTest::mouseClick(source.view->viewport(),Qt::LeftButton,Qt::NoModifier,source.view->visualRect(source.model->index(1,1)).center());QApplication::processEvents();
  const QString expected="='[Activated Source.xlsx]Sheet1'!$B$2";
  require(origin.bar->text()==expected&&source.bar->text()==expected,"clicking the directly activated workbook points into the original formula");
  QTest::keyClick(source.view,Qt::Key_Return);QApplication::processEvents();origin.window.recalculateNow();
  require(origin.model->raw(0,0)==expected&&origin.model->numericValue(0,0)==42&&source.window.currentSession().snapshot()==sourceBefore,"direct window activation commits and calculates the link without editing its source");
  require(origin.window.executeCommand("undo")&&origin.window.currentSession().snapshotView().at("sheets")==before.at("sheets")&&origin.window.currentSession().snapshotView().value("links",Json::array())==before.value("links",Json::array()),"directly activated external formula and link metadata remain one Undo");
 }
}
void externalEscapeAfterWindowActivation(){
 for(bool inCell:{false,true}){
  Surface origin,source;require(origin.model->setData(origin.model->index(0,0),"keep"),"prepare original value for activation cancellation");const auto before=origin.window.currentSession().snapshot(),sourceBefore=source.window.currentSession().snapshot();origin.activate();QLineEdit* editor=origin.bar;
  if(inCell){QTest::keyClick(origin.view,Qt::Key_F2);editor=origin.view->activeCellEditor();require(editor,"inline cancellation begins in the actual cell editor");}
  editor->setFocus();editor->selectAll();QTest::keyClicks(editor,"=SUM(");source.activate();QTest::keyClick(source.view,Qt::Key_Escape);QApplication::processEvents();
  require(QApplication::activeWindow()==&origin.window&&origin.view->currentIndex()==origin.model->index(0,0)&&origin.bar->text()=="keep"&&origin.window.currentSession().snapshot()==before&&source.window.currentSession().snapshot()==sourceBefore,"Escape after direct activation restores the original cell, value and both histories");
 }
}
void neverSavedSourceKeepsTheDraft(){
 QTemporaryDir files;Surface origin,source;require(source.model->setData(source.model->index(1,1),"42"),"prepare an unnamed source value");const auto before=origin.window.currentSession().snapshot(),sourceBefore=source.window.currentSession().snapshot();origin.activate();origin.bar->setFocus();QTest::keyClicks(origin.bar,"=");source.activate();
 const auto draft=origin.bar->text();const auto originHistory=origin.window.currentSession().historyBytes(),sourceHistory=source.window.currentSession().historyBytes();
 auto click=[&]{QTest::mouseClick(source.view->viewport(),Qt::LeftButton,Qt::NoModifier,source.view->visualRect(source.model->index(1,1)).center());QApplication::processEvents();};click();
 require(origin.bar->text()==draft&&source.bar->text()==draft&&origin.window.currentSession().snapshot()==before&&source.window.currentSession().snapshot()==sourceBefore&&origin.window.currentSession().historyBytes()==originHistory&&source.window.currentSession().historyBytes()==sourceHistory,"pointing at a never-saved source preserves both workbooks, histories and the exact pending draft");
 require(!QApplication::activeModalWidget()&&source.window.statusBar()->currentMessage()=="Save this source workbook before linking to it.","an unnamed source explains the save requirement without a modal confirmation");
 require(source.window.saveWorkbook(files.filePath("Named Source.xlsx"))&&source.model->setData(source.model->index(1,1),"84"),"name the source and then make a genuine unsaved edit");const auto editedSource=source.window.currentSession().snapshot();click();
 require(origin.bar->text()=="='[Named Source.xlsx]Sheet1'!$B$2","retrying the same pending draft after naming the source inserts its actual identity");QTest::keyClick(source.view,Qt::Key_Return);QApplication::processEvents();origin.window.recalculateNow();
 require(origin.model->numericValue(0,0)==84&&source.window.currentSession().snapshot()==editedSource,"a named source's unsaved edits remain valid for pointing and live calculation");
}
