 origin.view->scrollTo(reference);QApplication::processEvents();QTest::mouseClick(origin.view->viewport(),Qt::LeftButton,Qt::NoModifier,origin.view->visualRect(reference).center());QApplication::processEvents();require(origin.bar->text()=="=C2"&&origin.window.currentSession().snapshot()==before,"same-workbook pointing creates the exact uncommitted local reference");QTest::keyClick(origin.bar,Qt::Key_Return,Qt::ControlModifier);QTest::keyRelease(origin.view,Qt::Key_Control);QApplication::processEvents();origin.window.recalculateNow();
 require(origin.model->raw(23,2)=="=C2"&&origin.model->numericValue(23,2)==43830,"local Point accepts the real formula and numeric date without fabricating a cache");
