 QTemporaryDir files;Surface origin,source;require(origin.model->setData(origin.model->index(0,0),"17",Qt::EditRole)&&source.model->setData(source.model->index(1,1),"42",Qt::EditRole),"prepare independent origin and source workbook cells");
