 const auto sourceBefore=source.window.currentSession().snapshot();const auto originBefore=origin.window.currentSession().snapshot();origin.activate();QLineEdit* editor=origin.bar;
 if(inCell){QTest::keyClick(origin.view,Qt::Key_F2);editor=origin.view->activeCellEditor();require(editor,"F2 opens a native origin editor");}
