 require(QApplication::activeWindow()==&origin.window&&origin.model->raw(0,0)==expected&&origin.view->currentIndex()==origin.model->index(1,0),"Enter commits to the original workbook and returns there with normal downward navigation");
 const Json canonical={{"name","Source Financials.xlsx"},{"path",files.filePath("Source Financials.xlsx").toStdString()},{"enabled",true}};
 require(origin.window.currentSession().snapshotView().value("links",Json::array())==Json::array({canonical}),"external pointing persists the actual canonical source path with the formula");
